window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-21791\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατάγνυμι</h1><div class=\"entry-meta\"><span>DGP · ordem 1006 na letra κ · nº geral 21791</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. κατάξω, aor. κατέαξα, perf. de sent. pas. κατέαγα; pas. fut. καταχθήσομαι, aor.1 κατεάχθην, part. καταχθείς, aor.2 κατεάγην, perf. κατεάγμαι) 1 quebrar; romper: νέα μέν μοι κατέαξε Ποσειδάων hom. Posidão despedaçou meu navio, κατέαγα τῆς κεφαλῆς ar. ou τὴν κεφαλήν dem. quebrei a cabeça 2 debilitar; enfraquecer: κατ. τὰς ψυχάς xen. debilitar o espírito, κατ. τὴν πατρίδα eur. enfraquecer a pátria.</p></section></article>\n<article id=\"entry-dgp-21792\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταγνύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1007 na letra κ · nº geral 21792</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) = κατάγνυμι.</p></section></article>\n<article id=\"entry-dgp-21793\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταγνυπόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1008 na letra κ · nº geral 21793</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">franzir a testa.</p></section></article>\n<article id=\"entry-dgp-21794\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατάγνωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1009 na letra κ · nº geral 21794</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 má opinião 2 repreensão 3 condenação. 〈καταγιγνώσκω〉</p></section></article>\n<article id=\"entry-dgp-21795\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταγνωστέον</h1><div class=\"entry-meta\"><span>DGP · ordem 1010 na letra κ · nº geral 21795</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de καταγιγνώσκω.</p></section></article>\n<article id=\"entry-dgp-21796\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταγοητεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1011 na letra κ · nº geral 21796</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 enganar como charlatão; enfeitiçar 2 falsificar.</p></section></article>\n<article id=\"entry-dgp-21797\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταγόρευσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1012 na letra κ · nº geral 21797</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de declarar, de explicar, de indicar. 〈καταγορεύω〉</p></section></article>\n<article id=\"entry-dgp-21798\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταγορεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1013 na letra κ · nº geral 21798</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 declarar abertamente algo, ac., a alguém, dat. ou πρός e ac. 2 dizer 3 acusar, denunciar alguém, gen.</p></section></article>\n<article id=\"entry-dgp-21799\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταγραφή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1014 na letra κ · nº geral 21799</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 traçado; desenho 2 desenho de perfil 3 descrição (de país) 4 inscrição em lista; lista; registro. 〈καταγράφω〉</p></section></article>\n<article id=\"entry-dgp-21800\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατάγραφος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1015 na letra κ · nº geral 21800</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pintado de diversas cores. 〈κατα­γράφω〉</p></section></article>\n<article id=\"entry-dgp-21801\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταγράφω</h1><div class=\"entry-meta\"><span>DGP · ordem 1016 na letra κ · nº geral 21801</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 esfolar; arranhar 2 gravar um traçado; desenhar 3 pintar; gravar 4 inscrever; registrar; fazer uma lista de, ac. 5 designar; destinar por escrito 6 prescrever 7 computar; calcular.</p></section></article>\n<article id=\"entry-dgp-21802\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταγυμνάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1017 na letra κ · nº geral 21802</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">exercitar com muito zelo; fortalecer pelo exercício.</p></section></article>\n<article id=\"entry-dgp-21803\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατάγχω</h1><div class=\"entry-meta\"><span>DGP · ordem 1018 na letra κ · nº geral 21803</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sufocar; estrangular.</p></section></article>\n<article id=\"entry-dgp-21804\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατάγω</h1><div class=\"entry-meta\"><span>DGP · ordem 1019 na letra κ · nº geral 21804</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. κατάξω, aor.1 κατῆξα, aor.2 κατήγαγον, perf. καταγήοχα) 1 conduzir para baixo; fazer descer; baixar: κατ. τὸν ∆ία plut. fazer descer Zeus, κατ. ἵππους ἐπὶ νῆας hom. conduzir os cavalos para as naus, κατ. ἐπὶ θάλατταν τὸ στράτευμα xen. conduzir o exército ao mar, κατ. ψυχὰς εἰς Ἀΐδαο hom. fazer descer as almas ao Hades, κατ. τὴν ἐκ τῶν ὀρῶν ὕλην εἰς τὸ ἄστυ plat. carregar a lenha do alto dos montes para a cidade 2 fazer descender de, ἀπό e gen.; fazer recuar (a origem) até, εἰς e ac.: κατ. γένος ἀπό τινος plut. fazer a estirpe descender de 3 conduzir do alto mar ao porto: κατ. ναῦν her. conduzir um navio ao porto, κατ. τινά hom. conduzir alguém (passageiro) ao porto, κατ. τοὺς ἐμπόρους pol. levar as mercadorias ao porto 4 impelir; induzir alguém: τὸν Κρήτηνδε κατήγαγεν ἲς ἀνέμοιο hom. a força do vento impeliu-o a Creta, κατ. σαγήνην plut. puxar para a terra a rede, τοῦ πνεύματος κλύδωνα κατάγοντος πολύν plut. já que o vento trazia enorme onda, ἐς κίνδυνον φανερὸν κατ. τὴν πόλιν tuc. impelir a cidade a um perigo evidente 5 diminuir a intensidade de, ac.: κατ. βοάν eur. baixar a voz 6 puxar o fio; fiar 7 desfiar; desenvolver: κατ. τὸν λόγον plat. desenvolver um discurso 8 trazer de volta: κατ. οἴκαδε xen. trazer de volta para a pátria, κατὰ δὲ φρόνιν ἤγαγε πολλήν hom. trouxe muita experiência, κατ. τυραννίδας ἐς τὰς πόλις her. restaurar as tiranias nas cidades, εἰς τὰς πατρίδας εἰρήνην κατ. pol. restaurar a paz na pátria 9 trazer; conseguir: κατ. χρυσὸν ἐκ πολέμου plut. trazer ouro da guerra, κατ. θρίαμβον plut. conquistar um triunfo ♦ méd. 10 descer em terra; desembarcar em, ac. ou εἰς e ac. 11 vir para ficar, para alojar-se em, εἰς e ac., na casa de alguém, παρά e dat. ou ὥς e ac.: εἰς πανδοκεῖον plut. vir morar numa estalagem, προξενεῖς κατάγονται ἀεὶ παρὰ σοὶ οἱ κράτιστοι αὐτῶν xen. os próxenos, os mais poderosos, sempre se alojam em tua casa 12 voltar: κατ. εἰς τὸ στρατόπεδον xen. voltar ao acampamento 13 fazer recuar (a origem) até, εἰς e ac.</p></section></article>\n<article id=\"entry-dgp-21805\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταγωγή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1020 na letra κ · nº geral 21805</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de aportar 2 ancoradouro 3 ponto de parada; estalagem 4 lugar para repousar 5 cadeira 6 descendência 7 queda (d’água). 〈κατάγω〉</p></section></article>\n<article id=\"entry-dgp-21806\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταγώγιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1021 na letra κ · nº geral 21806</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ponto de parada; albergue 2 estada; refúgio ♦ τὰ καταγώγια 3 festa do retorno, em Éfeso, em honra de Ártemis. 〈καταγωγή〉</p></section></article>\n<article id=\"entry-dgp-21807\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταγωνίζομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1022 na letra κ · nº geral 21807</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. καταγωνίσομαι, át. καταγωνιοῦμαι) 1 lutar contra alguém ou algo, ac. 2 vencer alguém, ac. ♦ pas. 3 ser vencido.</p></section></article>\n<article id=\"entry-dgp-21808\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδαίνυμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1023 na letra κ · nº geral 21808</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. καταδαίσομαι, aor. κατεδαισάμην) devorar; consumir. 〈κατά, δαίνυμι〉</p></section></article>\n<article id=\"entry-dgp-21809\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδαίομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1024 na letra κ · nº geral 21809</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(inf. aor. pas. καταδασθῆναι) ser devorado.</p></section></article>\n<article id=\"entry-dgp-21810\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδακρύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1025 na letra κ · nº geral 21810</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 verter lágrimas; chorar 2 fazer chorar.</p></section></article>\n<article id=\"entry-dgp-21811\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδαμάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1026 na letra κ · nº geral 21811</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">at. e méd. submeter; subjugar.</p></section></article>\n<article id=\"entry-dgp-21812\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδαπανάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1027 na letra κ · nº geral 21812</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 gastar; desperdiçar; consumir; esgotar ♦ méd. 2 ser pródigo.</p></section></article>\n<article id=\"entry-dgp-21813\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδάπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 1028 na letra κ · nº geral 21813</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 devorar 2 dilacerar.</p></section></article>\n<article id=\"entry-dgp-21814\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδαρθάνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1029 na letra κ · nº geral 21814</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. καταδαρθήσομαι, aor.2 κατέδαρθον, ép. κατέδραθον, perf. καταδεδάρθηκα) 1 adormecer; dormir 2 passar a noite.</p></section></article>\n<article id=\"entry-dgp-21815\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδεής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1030 na letra κ · nº geral 21815</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 carente de, gen. 2 pobre; indigente (pessoa) 3 vazio (coisa) de, gen.: χρημάτων κατ. ἀγγήια her. os recipientes vazios de riquezas ♦ καταδεέστερος comp. 4 inferior a alguém, gen., em ou por algo, ac.</p></section></article>\n<article id=\"entry-dgp-21816\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδείκνυμι</h1><div class=\"entry-meta\"><span>DGP · ordem 1031 na letra κ · nº geral 21816</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tornar conhecido; mostrar 2 mostrar; ensinar algo, ac. ou inf., a alguém, dat.: κατ. ποιεῖν τι her. ensinar a fazer algo, τελετὰς θ’ ἡμῖν κατέδειξε φόνων τ’ ἀπέ­χεσθαι ar. ensinou-nos os mistérios e a nos abster de crimes 3 descobrir; inventar 4 bíbl. criar: ὁ καταδείξας sept. o criador ♦ pas. 5 ser demonstrado ou provado; provar que, part.: [ἄτραπος] κατεδέδεκτο (jôn.) ἐοῦσα οὐδὲν χρηστή her. o atalho estava comprovado como inútil.</p></section></article>\n<article id=\"entry-dgp-21817\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδειλιάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1032 na letra κ · nº geral 21817</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ficar paralizado de medo 2 recuar de medo diante de, ac.</p></section></article>\n<article id=\"entry-dgp-21818\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδειπνέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1033 na letra κ · nº geral 21818</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comer; devorar. 〈κατάδειπνον〉</p></section></article>\n<article id=\"entry-dgp-21819\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατάδειπνον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1034 na letra κ · nº geral 21819</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 refeição 2 pastagem. 〈κατά, δεῖπνον〉</p></section></article>\n<article id=\"entry-dgp-21820\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδέξας</h1><div class=\"entry-meta\"><span>DGP · ordem 1035 na letra κ · nº geral 21820</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor. jôn. de καταδείκνυμι.</p></section></article>\n<article id=\"entry-dgp-21821\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδέομαι1</h1><div class=\"entry-meta\"><span>DGP · ordem 1036 na letra κ · nº geral 21821</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. κατεδεήθην) suplicar, gen.</p></section></article>\n<article id=\"entry-dgp-21822\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδέομαι2-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1037 na letra κ · nº geral 21822</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">méd. de καταδέω1.</p></section></article>\n<article id=\"entry-dgp-21823\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδέρκομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1038 na letra κ · nº geral 21823</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. καταδέρξομαι, aor.1 κατεδέρχθην) olhar do alto; contemplar, ac. ou ἐπί e ac.</p></section></article>\n<article id=\"entry-dgp-21824\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατάδεσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1039 na letra κ · nº geral 21824</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de ligar, de prender 2 ação de fazer, com um nó, um sortilégio 3 nó mágico. 〈καταδέω1〉</p></section></article>\n<article id=\"entry-dgp-21825\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1040 na letra κ · nº geral 21825</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 molhar; umedecer; regar 2 bíbl. comover-se; amolecer.</p></section></article>\n<article id=\"entry-dgp-21826\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδέχομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1041 na letra κ · nº geral 21826</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. καταδεχθήσομαι e aor. κατεδέχθην) 1 tomar (alimento, bebida) 2 receber; aceitar; acolher: κατ. τινὰ ἐπὶ γάμον luc. receber alguém em casamento, κατ. τινὰ εἰς τὴν ψυχήν plat. acolher alguém em seu coração 3 receber de volta em casa (um exilado).</p></section></article>\n<article id=\"entry-dgp-21827\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδέω1-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1042 na letra κ · nº geral 21827</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 atar firmemente; prender fortemente algo ou alguém, ac., a, ἐπί ou ἐν e dat.: κατ. ἱστὸν προτό­νοισιν hom. prender fortemente um mastro com cabos, ἵππους μὲν κατέδησαν ἱμάσι ἔφ’ ἱππείῃ ἐπὶ φάτνῃ hom. prenderam com cordas os cavalos à manjedoura equina, κατ. τινὰ ἐν δεσμῷ pôr alguém na prisão, prender alguém, κατ. τὴν ἐπὶ θανάτῳ her. prender para levar à morte 2 vendar; tapar: κατ. τοὺς ὀφθαλμούς her. fechar os olhos, vendar os olhos, κατ. ἀνέμων κελεύθους ou κέλευθα hom. fechar o caminho dos ventos, κατ. νόστον hom. impedir o retorno 3 deter o culpado depois de condenado; condenar: κατ. τινὰ φῶρα εἶναι her. condenar alguém por ser ladrão ♦ méd. 4 prender para si ou em si: κατεδήσατο ἀγχόνιον βρόχον eur. enforcou-se com um laço.</p></section></article>\n<article id=\"entry-dgp-21828\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδέω2-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1043 na letra κ · nº geral 21828</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 carecer de, gen.: ἡ ὁδὸς καταδέει πεντε­καίδεκα σταδίων, ὡς μὴ εἶναι πεντακοσίων her. faltam 15 estádios para que o caminho tenha 500, πυραμίδα εἴκοσι ποδῶν καταδέουσαν… τριῶν πλέθρων her. pirâmides de 3 pletros menos 20 pés 2 ser inferior a alguém, gen., em algo, εἰς e ac.: κατ. τίνος εἰς εὐδαιμονίαν paus. ser menos feliz do que alguém.</p></section></article>\n<article id=\"entry-dgp-21829\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδεῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 1044 na letra κ · nº geral 21829</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de modo incompleto; de modo insuficiente.</p></section></article>\n<article id=\"entry-dgp-21830\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατάδηλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1045 na letra κ · nº geral 21830</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">muito claro; muito evidente; visível: κατ. γενέσθαι her. ser descoberto, κατάδηλον ποιῆσαι her. tornar conhecido, desmascarar. 〈κατά, δῆλος〉</p></section></article>\n<article id=\"entry-dgp-21831\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδημαγωγέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1046 na letra κ · nº geral 21831</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ser excessivo no uso de medidas demagógicas; conquistar com demagogia 2 suplantar em favor popular.</p></section></article>\n<article id=\"entry-dgp-21832\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδημοβορέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1047 na letra κ · nº geral 21832</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">devorar em comum no meio do povo; consumir.</p></section></article>\n<article id=\"entry-dgp-21833\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδιαιτάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1048 na letra κ · nº geral 21833</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. καταδιατήσω, aor. κατεδιῄτησα, perf. καταδεδιῄτηκα, m.-q.-perf. καταδεδιῃτήκειν; perf. pas. καταδεδιῄτημαι) 1 condenar: κατ. δίκην dem. condenar em processo, ἔρημον κατ. τινός (δίκην) dem. julgar alguém em sua ausência ou por contumácia ♦ méd. 2 levar à condenação com sentença arbitral: κατ. δίαιτάν τινος lís. ser causa de processo, de julgamento contra alguém, κατ. ἐρήμην τινός condenar alguém por contumácia.</p></section></article>\n<article id=\"entry-dgp-21834\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδιαφθείρω</h1><div class=\"entry-meta\"><span>DGP · ordem 1049 na letra κ · nº geral 21834</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">διαφθείρω.</p></section></article>\n<article id=\"entry-dgp-21835\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδίδωμι</h1><div class=\"entry-meta\"><span>DGP · ordem 1050 na letra κ · nº geral 21835</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 partilhar; distribuir 2 (subent. ἑαυτόν) jogar-se em (rio), εἰς e ac.</p></section></article>\n<article id=\"entry-dgp-21836\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδικάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1051 na letra κ · nº geral 21836</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pronunciar um julgamento contra; condenar alguém, gen. ou ac., a algo, ac. ou inf.: κατ. θάνατόν τι­νος her. condenar alguém a morte, κατ. τινὸς τὰ ἔσχατα πα­θεῖν xen. condenar alguém a sofrer o último suplício, κ. τινὰ ἀποθα­νεῖν luc. condenar alguém à morte 2 declarar em julgamento que, or. conj. (ὅτι) ♦ méd. 3 perseguir na justiça; fazer condenar alguém, gen.: κατ. χρημάτων τινός paus. fazer condenar por peculato, δίκην καταδικάσασθαί τινος tuc. conseguir a condenação de alguém 4 bíbl. obter sentença favorável.</p></section></article>\n<article id=\"entry-dgp-21837\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδίκη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1052 na letra κ · nº geral 21837</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 condenação; sentença condenatória 2 punição; pena; multa. 〈κατά, δίκη〉</p></section></article>\n<article id=\"entry-dgp-21838\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδιφθερόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1053 na letra κ · nº geral 21838</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cobrir inteiramente com peles. 〈κατά, διφθέρα〉</p></section></article>\n<article id=\"entry-dgp-21839\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδιώκω</h1><div class=\"entry-meta\"><span>DGP · ordem 1054 na letra κ · nº geral 21839</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ir no encalço de; perseguir 2 bíbl. buscar diligentemente 3 forçar a fugir; enxotar.</p></section></article>\n<article id=\"entry-dgp-21840\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδοκέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1055 na letra κ · nº geral 21840</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. κατέδοξα) 1 ter opinião contrária ou desfavorável; desconfiar; suspeitar de alguém, dat., que, or. inf. ou rel.: κατ. τινὰ ποιεῖν τι her. desconfiar que alguém faz algo, οὐ γὰρ ἄν κοτε κατέδοξαν ἔνθεν γε ἦν her. nunca teria suspeitado de onde ele era ♦ pas. 2 ser alvo de suspeita; encontrar-se sob suspeita.</p></section></article>\n<article id=\"entry-dgp-21841\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδολεσχέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1056 na letra κ · nº geral 21841</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cansar com a tagarelice, gen.</p></section></article>\n<article id=\"entry-dgp-21842\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδοξάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1057 na letra κ · nº geral 21842</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">καταδοκέω.</p></section></article>\n<article id=\"entry-dgp-21843\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδουλόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1058 na letra κ · nº geral 21843</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tornar alguém, ac., escravo de outrem, dat. 2 subjugar; dominar (cidade), ac. ou dat. 3 tornar servil e covarde; aviltar ♦ méd. 4 escravizar para si; submeter.</p></section></article>\n<article id=\"entry-dgp-21844\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδούλωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1059 na letra κ · nº geral 21844</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sujeição; escravidão. 〈κατά, δουλόω〉</p></section></article>\n<article id=\"entry-dgp-21845\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατάδουπος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1060 na letra κ · nº geral 21845</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">catarata. 〈κατά, δοῦπος〉</p></section></article>\n<article id=\"entry-dgp-21846\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδραθῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1061 na letra κ · nº geral 21846</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">subj. aor. pas. ép. de καταδαρθάνω.</p></section></article>\n<article id=\"entry-dgp-21847\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδραμεῖν</h1><div class=\"entry-meta\"><span>DGP · ordem 1062 na letra κ · nº geral 21847</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 de κατατρέχω.</p></section></article>\n<article id=\"entry-dgp-21848\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδρέπω</h1><div class=\"entry-meta\"><span>DGP · ordem 1063 na letra κ · nº geral 21848</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">colher.</p></section></article>\n<article id=\"entry-dgp-21849\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδρομή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1064 na letra κ · nº geral 21849</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 incursão 2 lugar de repouso; refúgio; asilo. 〈καταδραμεῖν〉</p></section></article>\n<article id=\"entry-dgp-21850\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδυναστεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1065 na letra κ · nº geral 21850</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">oprimir; subjugar; tiranizar, ac. ou gen.</p></section></article>\n<article id=\"entry-dgp-21851\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1066 na letra κ · nº geral 21851</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf. κατέδυνον) = καταδύω.</p></section></article>\n<article id=\"entry-dgp-21852\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδύσεο</h1><div class=\"entry-meta\"><span>DGP · ordem 1067 na letra κ · nº geral 21852</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. aor. poét. de καταδύω.</p></section></article>\n<article id=\"entry-dgp-21853\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατάδυσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1068 na letra κ · nº geral 21853</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de afundar ou de ser engolido 2 imersão; mergulho 3 Astron. ocaso 4 lugar onde se afunda; buraco 5 bíbl. o mundo presente (por estar sujeito a declínio). 〈καταδύω〉</p></section></article>\n<article id=\"entry-dgp-21854\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδυσωπέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1069 na letra κ · nº geral 21854</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perturbar; emocionar; dobrar.</p></section></article>\n<article id=\"entry-dgp-21855\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1070 na letra κ · nº geral 21855</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. κατέδυον, fut. καταδύσω, aor.1 κατέδυσα, aor.2 κατέδυν, perf. καταδέδυκα; méd. καταδύομαι, fut. καταδύσομαι) 1 fazer afundar; mergulhar: κατ. τινὰ τῷ ἄχει xen. mergulhar alguém na dor ♦ at. (aor.2 e perf.) e méd. 2 afundar-se; mergulhar na água; (navio) afundar no mar; naufragar: ἠέλιος κατέδυ hom. o sol mergulhou (no oceano), ἡ νῆσος καταδέδυκε κατὰ θαλάσσης her. a ilha afundou no mar abaixo 3 penetrar; descer; entrar: κατ. εἰς Ἀΐδαο δόμους hom. mergulhar na morada de Hades 4 penetrar; entrar; infiltrar-se: κατ. ὅμιλον hom. infiltrar-se na multidão, κατ. μάχην hom. entrar na batalha, κατ. πόλιν hom. penetrar na cidade 5 penetrar; insinuar-se: κατ. εἰς τὸ ἐντὸς τῆς ψυχῆς plat. [harmonia] penetrar no íntimo da alma 6 cobrir-se de; revestir-se de, ac.: κατ. τεύχεα hom. revestir-se de armas 7 esconder-se: κατ. ὑπὸ τῆς αἰσχύνης xen. esconder-se de vergonha, κατ. ἐς ὕλην her. ocultar-se na floresta, κατδεδυκὼς ἐν τῇ οἰκίᾳ plat. oculto em casa.</p></section></article>\n<article id=\"entry-dgp-21856\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατᾴδω</h1><div class=\"entry-meta\"><span>DGP · ordem 1071 na letra κ · nº geral 21856</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. κατῇδον, fut. κατᾴσομαι) 1 (pássaro) cantar do alto de, de cima de 2 encher de canto; fazer ressoar 3 aplacar com cantos 4 encantar; aliviar com encantos 5 cantar uma fórmula de encantamento contra, dat.; cantar contra (para esconjurar): καταείδοντες τῷ ἀνέμῳ her. acalmando o vento com cantos mágicos, apaziguar o vento, κατ. βάρβαρα μέλη eur. cantar cantos bárbaros (encantamentos) 6 cantar contra; zombar com cantos; compor cantos satíricos ♦ pas. 7 ser conduzido por encantamento, inf.</p></section></article>\n<article id=\"entry-dgp-21857\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταδωροδοκέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1072 na letra κ · nº geral 21857</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">at. e méd. 1 corromper com presentes ♦ intr. e pas. 2 deixar-se corromper com presentes.</p></section></article>\n<article id=\"entry-dgp-21858\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταείδω</h1><div class=\"entry-meta\"><span>DGP · ordem 1073 na letra κ · nº geral 21858</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = κατᾴδω.</p></section></article>\n<article id=\"entry-dgp-21859\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταειμένος</h1><div class=\"entry-meta\"><span>DGP · ordem 1074 na letra κ · nº geral 21859</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. perf. pas., καταείνυον 3ª pl. impf. at., de καταέννυμι.</p></section></article>\n<article id=\"entry-dgp-21860\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταείσατο</h1><div class=\"entry-meta\"><span>DGP · ordem 1075 na letra κ · nº geral 21860</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. aor. méd. ép. de κάτειμι.</p></section></article>\n<article id=\"entry-dgp-21861\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταέννυμι</h1><div class=\"entry-meta\"><span>DGP · ordem 1076 na letra κ · nº geral 21861</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">vestir; cobrir: κατ. θριξὶ νέκυν hom. vestir ou cobrir um morto com cabelos (como forma de homenagem), ὄρος καταειμένον ὕλῃ hom. montanha coberta de floresta.</p></section></article>\n<article id=\"entry-dgp-21862\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταζαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1077 na letra κ · nº geral 21862</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. iter. καταζήνασκον) ép. fazer secar completamente.</p></section></article>\n<article id=\"entry-dgp-21863\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταζάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1078 na letra κ · nº geral 21863</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(para o aor. e perf. cf. καταβιόω) passar a vida.</p></section></article>\n<article id=\"entry-dgp-21864\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταζεύγνυμι</h1><div class=\"entry-meta\"><span>DGP · ordem 1079 na letra κ · nº geral 21864</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 atrelar junto: κατ. ἐν ἅρματι σθένος ἵπ­πιον pínd. atrelar a um carro vigorosos cavalos 2 fazer uma parada; montar acampamento ♦ pas. 3 ser ou estar preso, constrangido: κατ. ὑπ’ ἀναγκαίης her. estar preso ou constrangido pela necessidade 4 ser encerrado, ἐν e dat.</p></section></article>\n<article id=\"entry-dgp-21865\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατάζευξις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1080 na letra κ · nº geral 21865</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 atrelagem 2 parada 3 estada; acampamento. 〈καταζεύγνυμι〉</p></section></article>\n<article id=\"entry-dgp-21866\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταζήνασκον</h1><div class=\"entry-meta\"><span>DGP · ordem 1081 na letra κ · nº geral 21866</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. καταζαίνω.</p></section></article>\n<article id=\"entry-dgp-21867\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταζώννυμι</h1><div class=\"entry-meta\"><span>DGP · ordem 1082 na letra κ · nº geral 21867</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cingir; envolver ♦ méd. 2 cingir-se 3 cingir; envolver.</p></section></article>\n<article id=\"entry-dgp-21868\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταθάλπω</h1><div class=\"entry-meta\"><span>DGP · ordem 1083 na letra κ · nº geral 21868</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aquecer fortemente.</p></section></article>\n<article id=\"entry-dgp-21869\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταθαμβέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1084 na letra κ · nº geral 21869</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ver com surpresa; ficar atônito 2 temer diante de, ac.</p></section></article>\n<article id=\"entry-dgp-21870\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταθάπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 1085 na letra κ · nº geral 21870</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(inf. aor. poét. κατθάψαι) sepultar.</p></section></article>\n<article id=\"entry-dgp-21871\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταθαρσύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1086 na letra κ · nº geral 21871</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e καταθαρρύνω encorajar alguém, ac., contra ou diante de, πρός e ac.: κατ. τινὰ πρὸς τὸ μέλ­λον plut. encorajar alguém diante do futuro.</p></section></article>\n<article id=\"entry-dgp-21872\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταθεάομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1087 na letra κ · nº geral 21872</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 olhar do alto; contemplar 2 olhar atentamente.</p></section></article>\n<article id=\"entry-dgp-21873\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταθεῖναι</h1><div class=\"entry-meta\"><span>DGP · ordem 1088 na letra κ · nº geral 21873</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 at., καταθείομαι subj. aor.2 méd. poét., καταθείομεν 1ª pl. subj. aor.2 poét. at., de κατατίθημι.</p></section></article>\n<article id=\"entry-dgp-21874\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταθέλγω</h1><div class=\"entry-meta\"><span>DGP · ordem 1089 na letra κ · nº geral 21874</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 transformar por sortilégios 2 encantar; enfeitiçar.</p></section></article>\n<article id=\"entry-dgp-21875\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατάθελξις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1090 na letra κ · nº geral 21875</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de encantar, de fascinar; encantamento. 〈καταθέλγω〉</p></section></article>\n<article id=\"entry-dgp-21876\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατάθεμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1091 na letra κ · nº geral 21876</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. = κατανάθεμα.</p></section></article>\n<article id=\"entry-dgp-21877\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταθεματίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1092 na letra κ · nº geral 21877</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. = καταναθεματίζω.</p></section></article>\n<article id=\"entry-dgp-21878\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατάθεσθαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1093 na letra κ · nº geral 21878</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 méd. de κατατίθημι.</p></section></article>\n<article id=\"entry-dgp-21879\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταθέω</h1><div class=\"entry-meta\"><span>DGP · ordem 1094 na letra κ · nº geral 21879</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. καταθεύσομαι) 1 descer correndo: κατ. ἀπὸ λόφων tuc. descer correndo das montanhas 2 voltar do alto mar; aportar: κατ. εἰς Πειραιᾶ xen. aportar no Pireu 3 correr contra; fazer uma incursão contra, ac. ou εἰς e ac. 4 perseguir; atacar; devastar 5 pressionar com reflexões.</p></section></article>\n<article id=\"entry-dgp-21880\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταθήκη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1095 na letra κ · nº geral 21880</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">objeto depositado; depósito. 〈κατα­τίθημι〉</p></section></article>\n<article id=\"entry-dgp-21881\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταθηλύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1096 na letra κ · nº geral 21881</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(part. perf. pas. κατατεθηλυμμένος ou -λυσμένος) efeminar; enfraquecer.</p></section></article>\n<article id=\"entry-dgp-21882\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταθλέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1097 na letra κ · nº geral 21882</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 vencer em combate; superar: κατ. τὴν ἀμαθίαν plut. vencer a ignorância 2 exercitar alguém, ac., em algo, ἐν e dat. 3 exercitar-se para combates: κατηθληκότες plut. [soldados] bem exercitados.</p></section></article>\n<article id=\"entry-dgp-21883\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταθλίβω</h1><div class=\"entry-meta\"><span>DGP · ordem 1098 na letra κ · nº geral 21883</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 estreitar 2 esmagar 3 sufocar.</p></section></article>\n<article id=\"entry-dgp-21884\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταθνῄσκω</h1><div class=\"entry-meta\"><span>DGP · ordem 1099 na letra κ · nº geral 21884</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. sinc. κατθανοῦμαι, aor.2 sinc. κάτθανον, perf. κατατέθνηκα, part. ép. κατατεθνηώς, gen. fem. jôn. κατατεθνηυίης) morrer; desaparecer.</p></section></article>\n<article id=\"entry-dgp-21885\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταθνητός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1100 na letra κ · nº geral 21885</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">mortal; perecível. 〈καταθνῄσκω〉</p></section></article>\n<article id=\"entry-dgp-21886\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταθοινάομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1101 na letra κ · nº geral 21886</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. κατεθοινησάμην) alimentar-se de; devorar.</p></section></article>\n<article id=\"entry-dgp-21887\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταθρασύνομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1102 na letra κ · nº geral 21887</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">καταθαρσύνω.</p></section></article>\n<article id=\"entry-dgp-21888\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταθραύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1103 na letra κ · nº geral 21888</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 separar em grupos 2 quebrar; fraturar; despedaçar.</p></section></article>\n<article id=\"entry-dgp-21889\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταθρηνέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1104 na letra κ · nº geral 21889</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">chorar sobre; deplorar.</p></section></article>\n<article id=\"entry-dgp-21890\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταθρώσκω</h1><div class=\"entry-meta\"><span>DGP · ordem 1105 na letra κ · nº geral 21890</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. καταθοροῦμαι, aor.2 κατέθορον) 1 lançar-se de cima para baixo, ἀπὸ e gen. 2 lançar-se por cima de; transpor de um salto, ac. 3 lançar-se contra, gen. ou εἰς e ac.</p></section></article>\n";
